result = [3, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 2, 3, 2, 2, 3, 3, 3, 1, 0, 1, 0, 0, 2, 1]
# Verify the result
subsets = {0: [], 1: [], 2: [], 3: [], 4: []}
for i, subset_idx in enumerate(result):
    subsets[subset_idx].append(i + 1)

print("Subsets:", subsets)
for j in range(5):
    print(f"Sum of subset {j}: {sum(subsets[j])}")
